    "id": 12,
    "title": "YoloTag: Vision-based Robust UAV Navigation with Fiducial Markers",
    "year": "2024",
    "category": "Conference Paper",
    "venue": "IEEE International Conference on Robot & Human Interactive Communication (RO-MAN)",
    "journal": "IEEE International Conference on Robot & Human Interactive Communication (RO-MAN)",
    "link": "https://arxiv.org/abs/2409.02334",
